private static void checkVectorSize(XmlContext context, Element element) {
    if (context.getMainProject().getMinSdk() >= 21) {
        return;
    }
    int maxWidth = -1;
    int maxHeight = -1;
    String widthValue = null;
    String heightValue = null;
    NamedNodeMap attributes = element.getAttributes();
    for (int i = 0, n = attributes.getLength(); i < n; i++) {
        Attr attr = (Attr) attributes.item(i);
        String name = attr.getLocalName();
        if (name == null) name = attr.getName();
        if ("width".equals(name)) {
            widthValue = attr.getValue();
            maxWidth = getSizeInDp(widthValue);
        } else if ("height".equals(name)) {
            heightValue = attr.getValue();
            maxHeight = getSizeInDp(heightValue);
        }
    }
    if (maxWidth > MAX_DIMENSION_DP || maxHeight > MAX_DIMENSION_DP) {
        context.report(ISSUE, context.getLocation(element),
            "This vector icon is very large ("
                + (widthValue != null ? widthValue : "?") + " x "
                + (heightValue != null ? heightValue : "?")
                + "), which will result in large generated PNGs. Consider reducing the size.");
    }
}
