private static int getSizeInDp(String value) {
    if (value == null) return -1;
    int len = value.length();
    if (len > 2 && value.endsWith("dp")) {
        try {
            return Math.round(Float.parseFloat(value.substring(0, len - 2).trim()));
        } catch (NumberFormatException e) {
            return -1;
        }
    }
    return -1;
}
```

